etained","isbn13":"9789064032295","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":12040529,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL34490134M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987239021,"bound_title":"Macbeth","reviewed_at":"2026-11-03T08:16:03.676+00:00","bound_isbn13":"9789064032295","evidence_url":"https://data.bibliotheken.nl/id/nbt/p05864119X","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987311001},"before_row":null},{"key":{"open_library_edition_id":"OL32890293M"},"seq":9,"relation":"editions","after_row":{"id":987239022,"title":"The Hate U Give","isbn_10":null,"isbn_13":"9789048848607","work_id":987139007,"cover_id":null,"language":"dut","publisher":"Moon young adult","publish_date":null,"open_library_edition_id":"OL32890293M"},"before_row":null},{"key":{"work_id":987139007,"language":"nl"},"seq":10,"relation":"catalog_work_descriptions","after_row":{"text":"De zestienjarige Starr leeft tussen twee werelden: haar eigen buurt en de welgestelde privéschool waar zij les krijgt. Wanneer een politieagent haar jeugdvriend Khalil doodschiet, is zij getuige. Het incident krijgt grote publieke aandacht en maakt zwijgen steeds moeilijker. Starr moet afwegen wat het betekent om haar stem te laten horen, terwijl verschillende mensen iets van haar verwachten. Haar persoonlijke verlies raakt zo verweven met vragen over loyaliteit, racisme en de manier waarop een verhaal wordt verteld.","work_id":987139007,"evidence":[{"note":"Exact Dutch translation9789048848607, Moon youngadult; English-looking title TheHateUGive is not evidence ofEnglish language. Starr/Khalil identity and2017original match, notfilm.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p420861335","http://data.bibliotheken.nl/id/nbt/p434286044"],"reference":"work:452","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://openlibrary.org/works/OL17714701W","https://data.bibliotheken.nl/id/nbt/p420861335","https://data.bibliotheken.nl/id/nbt/p434286044"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789048848607","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":11521444,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL32890293M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL17714701W","reviewed_at":"2026-11-03T08:16:03.676+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_author_id":987339004},"before_row":null},{"key":{"edition_id":987239022},"seq":11,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987139007,"evidence":[{"note":"Exact Dutch translation9789048848607, Moon youngadult; English-looking title TheHateUGive is not evidence ofEnglish language. Starr/Khalil identity and2017original match, notfilm.","type":"reviewed_identity_and_bibli