illen beheersen.","work_id":987139011,"evidence":[{"note":"JohnGrisham TheClient1993 MarkSway/ReggieLove, exactfullDutchpaperback9789022981948, notReadersDigest abridgement orfilm.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p124872301"],"reference":"work:561","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-017.json","sources":["http://www.jgrisham.com/books/the-client/","https://openlibrary.org/works/OL77022W","https://data.bibliotheken.nl/id/nbt/p124872301"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789022981948","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":11015814,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL32366726M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL77022W","reviewed_at":"2026-11-03T08:16:03.676+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_author_id":987339006},"before_row":null},{"key":{"edition_id":987239027},"seq":26,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987139011,"evidence":[{"note":"JohnGrisham TheClient1993 MarkSway/ReggieLove, exactfullDutchpaperback9789022981948, notReadersDigest abridgement orfilm.","type":"reviewed