ions","after_row":{"id":987239032,"title":"Wicked","isbn_10":null,"isbn_13":"9789044369236","work_id":987139001,"cover_id":null,"language":"dut","publisher":"The House of Books","publish_date":null,"open_library_edition_id":"OL60650924M"},"before_row":null},{"key":{"work_id":987139001,"language":"nl"},"seq":40,"relation":"catalog_work_descriptions","after_row":{"text":"Elphaba groeit op met een groene huid in een wereld waarin afkomst en afwijking veel bepalen. Het land Oz is hier geen eenvoudig sprookjesrijk: ook dieren eisen een volwaardige plaats op en politieke belangen sturen het dagelijks leven. Vanuit het perspectief van de latere boze heks krijgt het bekende verhaal een andere betekenis. De roman vraagt hoe iemand als slecht wordt bestempeld en wat er buiten beeld blijft wanneer een geschiedenis maar vanuit één kant wordt verteld.","work_id":987139001,"evidence":[{"note":"GregoryMaguire Wicked1995, exactDutch9789044369236 complete novel, not BaumOzoriginal norstage/musical/filmadaptation.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p44331540X"],"reference":"work:246","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://openlibrary.org/works/OL66218W","https://data.bibliotheken.nl/id/nbt/p44331540X"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789044369236","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15143544,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL60650924M","limitation":"No 