 herinnering aan hun laatste gezamenlijke dag bewust manipuleert.","work_id":987139012,"evidence":[{"note":"CobenTellNoOne2001, exactDutchNiemandVertellen9789022530450; currentWorkyear2000 conflicts with exactKBoriginalDelacorte2001 and publishercolophon. Preserve sameexistingWork, notFrenchfilm.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p237530015"],"reference":"work:585","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://www.hugendubel.info/annot/564C42696D677C7C393738333434323438323635387C7C504446.pdf?sq=1","https://openlibrary.org/works/OL79319W","https://data.bibliotheken.nl/id/nbt/p237530015"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789022530450","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15205065,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL45867977M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL79319W","reviewed_at":"2026-11-03T08:16:03.676+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_author_id":987304003},"before_row":null},{"key":{"edition_id":987239034},"seq":48,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987